<?php $title='Damage Ledger'; $pageUrl=static fn(array $changes):string=>'?'.http_build_query(array_merge($query??[],$changes)); ?><?= view('vehicle_wheel_history/_start',get_defined_vars()) ?>
<?= view('vehicle_wheel_history/_strip',['projection'=>$projection]) ?>
<form method="get" aria-label="Damage filters">
<label>Wheel<select name="wheel"><?php foreach([''=>'All positions','LF'=>'Left front (LF)','RF'=>'Right front (RF)','RR'=>'Right rear (RR)','LR'=>'Left rear (LR)','UNKNOWN'=>'Unknown'] as $code=>$label): ?><option value="<?= esc($code,'attr') ?>"<?= $filters['wheel']===$code?' selected':'' ?>><?= esc($label) ?></option><?php endforeach; ?></select></label>
<label>Damage type<select name="damage_type"><option value="">All damage types</option><?php foreach(\App\Services\Fleet\VehicleDamageService::DAMAGE_TYPES as $code=>$label): ?><option value="<?= esc($code,'attr') ?>"<?= $filters['damage_type']===$code?' selected':'' ?>><?= esc($label) ?></option><?php endforeach; ?></select></label>
<label>Physical status today<select name="physical_status"><?php foreach([''=>'All physical statuses','current'=>'Current','repaired'=>'Repaired','resolved'=>'Resolved'] as $code=>$label): ?><option value="<?= esc($code,'attr') ?>"<?= $filters['physical_status']===$code?' selected':'' ?>><?= esc($label) ?></option><?php endforeach; ?></select></label>
<label>Identity to search<select name="identity"><option value="current"<?= $filters['identity']==='current'?' selected':'' ?>>Current canonical condition</option><option value="recorded"<?= $filters['identity']==='recorded'?' selected':'' ?>>Recorded occurrence identity</option></select></label>
<label>Description or occurrence note<input name="q" maxlength="190" value="<?= esc($filters['q'],'attr') ?>"></label><button type="submit">Apply filters</button></form>
<p>Physical condition status is separate from repair job status. Recorded-occurrence searches use the wheel recorded at that time; physical status is shown as it stands today.</p>
<p><a href="/fleet/vehicles/<?= (int)$vehicle['id'] ?>/wheel-damage/new">Record wheel occurrence</a></p>
<p>Clock positions are referenced with the valve stem at 12 o'clock.</p>
