<?php foreach($results as $row): ?><article><h2><?= esc(\App\Services\Fleet\VehicleWheelIdentity::conditionLabel($row)) ?> · <?= esc(\App\Services\Fleet\VehicleDamageService::DAMAGE_TYPES[$row['damage_type_code']]??$row['damage_type_code']) ?></h2><p><?= esc(\App\Services\Fleet\VehicleDamageService::STATUSES[$row['status_code']]??$row['status_code']) ?></p><p><?= nl2br(esc((string)($filters['identity']==='recorded'?$row['note']:$row['description']))) ?></p>
<?php if($filters['identity']==='recorded'): ?><p><?= esc(\Config\VehicleDamage::EFFECTS[$row['effect_code']]??$row['effect_code']) ?></p><a href="/fleet/vehicles/<?= (int)$vehicle['id'] ?>/wheel-history/<?= (int)$row['original_condition_id'] ?>/occurrences/<?= (int)$row['id'] ?>">View recorded occurrence</a><?php else: ?><a href="/fleet/vehicles/<?= (int)$vehicle['id'] ?>/damage/<?= (int)$row['id'] ?>">View condition record</a><?php endif; ?></article><?php endforeach; ?>
<nav aria-label="Damage results pages"><?php if($page>1): ?><a href="<?= esc($pageUrl(array_merge($filters,['page'=>$page-1])),'attr') ?>">Previous records</a><?php endif; ?><?php if($has_next): ?><a href="<?= esc($pageUrl(array_merge($filters,['page'=>$page+1])),'attr') ?>">Next records</a><?php endif; ?></nav></main></body></html>
